/**
 * Subpath module of the fake vendor package. These names are NOT re-exported from the package
 * root (`index.d.ts` below re-exports `Plugin` only) — the same shape graphql-yoga has.
 */
export type OnExecuteHook<TContext> = (context: TContext) => void;
export type OnParamsHook<TContext> = (context: TContext) => void;
export type OnPluginInitHook<TContext> = (context: TContext) => void;

export type ServerAdapterPlugin<TServerContext> = {
  onRequest?: (serverContext: TServerContext) => void;
};

/** Generic whose target is a structural intersection, exactly like yoga's `Plugin`. */
export type Plugin<TContext> = ServerAdapterPlugin<{}> & {
  onExecute?: OnExecuteHook<TContext>;
  onParams?: OnParamsHook<TContext>;
  onPluginInit?: OnPluginInitHook<TContext>;
};
